import { sendCharge, type ChargeRequest } from "./charge";
import { sleep } from "../util/sleep";

const MAX_ATTEMPTS = 3;
const BASE_DELAY_MS = 200;

/** One key per order, so the provider drops a repeated charge. */
export function idempotencyKey(orderId: string): string {
  return `order_${orderId}_charge`;
}

export function backoff(attempt: number, random = Math.random): number {
  const base = BASE_DELAY_MS * 2 ** (attempt - 1);
  return base + Math.floor(random() * base * 0.2);
}

export async function chargeWithRetry(req: ChargeRequest) {
  const key = idempotencyKey(req.orderId);
  let lastError: unknown;
  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
    try {
      return await sendCharge({ ...req, idempotencyKey: key });
    } catch (err) {
      lastError = err;
      await sleep(backoff(attempt));
    }
  }
  throw lastError;
}
TS
