import { describe, expect, it } from "vitest";
import { backoff, idempotencyKey } from "./retry";

describe("chargeWithRetry", () => {
  it("sends the same key on every attempt", () => {
    expect(idempotencyKey("ord_81")).toBe("order_ord_81_charge");
  });

  it("waits longer after each attempt", () => {
    expect(backoff(1, () => 0)).toBe(200);
    expect(backoff(2, () => 0)).toBe(400);
  });
});
